    coeffs[50] = ComplexF64(0)
    return nothing
end

function construct_gsn_endpoint_basis_i_ic_splus2(lambda, m, nu, omega)
    lambda = ComplexF64(lambda)
    m = Float64(m)
    nu = Float64(nu)
    omega = ComplexF64(omega)
    l2 = lambda * lambda
    l3 = l2 * lambda
    m2 = m * m
    m3 = m2 * m
    m4 = m3 * m
    o2 = omega * omega
    o3 = o2 * omega
    o4 = o3 * omega
    s1 = sin(nu)
    c1 = sqrt((1 - s1) * (1 + s1))
    sn = s1
    c = c1
    cp2 = c * c
    cp3 = cp2 * c
    cp4 = cp3 * c
    cp5 = cp4 * c
    cp6 = cp5 * c
    cp7 = cp6 * c
    cp8 = cp7 * c
    cp9 = cp8 * c
    cp10 = cp9 * c
    cp11 = cp10 * c
    cp12 = cp11 * c
    cp13 = cp12 * c
    cp14 = cp13 * c
    cp15 = cp14 * c
    cp16 = cp15 * c
    cp17 = cp16 * c
    cp18 = cp17 * c
    u = s1 * s1 / (1 + c1)
    up2 = u * u
    up3 = up2 * u
    up4 = up3 * u
    up5 = up4 * u
    up6 = up5 * u
    up7 = up6 * u
    up8 = up7 * u
    up9 = up8 * u
    up10 = up9 * u
    coeffs = Vector{ComplexF64}(undef, LEN_GSN_ENDPOINT_i_ic_splus2)
    _construct_gsn_endpoint_basis_i_ic_splus2_block_1!(coeffs, lambda, m, omega, l2, m2, o2, sn, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, u, up2, up3, up4, up5)
    _construct_gsn_endpoint_basis_i_ic_splus2_block_2!(coeffs, lambda, m, omega, l2, m2, o2, sn, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, u, up2, up3, up4, up5, up6)
    _construct_gsn_endpoint_basis_i_ic_splus2_block_3!(coeffs, lambda, m, omega, l2, l3, m2, o2, o3, o4, sn, cp2, cp3, cp4, cp5, cp6, cp7, cp13, cp14, cp15, cp16, cp17, u, up2, up3, up4, up5, up6)
    _construct_gsn_endpoint_basis_i_ic_splus2_block_4!(coeffs, lambda, m, omega, l2, l3, m2, m3, m4, o2, o3, o4, sn, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, u, up2, up3, up4, up5, up6, up7)
    _construct_gsn_endpoint_basis_i_ic_splus2_block_5!(coeffs, lambda, m, omega, l2, l3, m2, m3, m4, o2, o3, o4, sn, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, u, up2, up4, up5, up6, up7, up8, up9, up10)
    _construct_gsn_endpoint_basis_i_ic_splus2_block_6!(coeffs, lambda, m, omega, l2, m2, o2, sn, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, u, up2, up3, up4, up5, up6, up7, up8)
    _construct_gsn_endpoint_basis_i_ic_splus2_block_7!(coeffs)
    return coeffs
end

